export type GateType = "kana" | "meaning" | "reading";

export type KanaItem = {
  char: string;
  romaji: string;
  script: "hiragana" | "katakana";
};

export type GateRow = {
  type: GateType;
  prompt: string;
  options: string[];
  answerIndex: number;
  answer: string;
};

/** A kanji from `src/data/kanji.json`, generated by `npm run data:build`. */
export type KanjiItem = {
  char: string;
  /** Progression level: 2 is the first kanji level, 30 kanji per level. */
  level: number;
  /** KANJIDIC2 school grade: 1–6, or 8 for the rest of Jōyō. */
  grade: number;
  /** Newspaper frequency rank, or null when unranked. */
  freq: number | null;
  /** English glosses; the first is the primary gloss shown on meaning gates. */
  glosses: string[];
  /** Main on'yomi in hiragana. */
  on: string | null;
  /** Main kun'yomi in hiragana, okurigana split out: あ(げる). */
  kun: { base: string; okurigana: string } | null;
  /** Every reading in hiragana (kun'yomi with okurigana), for excluding distractors. */
  readings: string[];
  /** KRADFILE elements, some of them kanji, some radicals such as ⺅. */
  components: string[];
};
